    def set_volume(self):
        logger.info(self.volume_slider.value())
        self.volume_label.setText(f'громкость {str(self.volume_slider.value())} %')
        if self.volume_slider.value() <= 100:
            self.volume_slider.setStyleSheet(volume_slider_style_default())
        else:
            self.volume_slider.setStyleSheet(volume_slider_style_overload())

